-- A chat reply is generated by the server, not by the open page: the `ai` function answers "started" at once and
-- goes on (EdgeRuntime.waitUntil), then writes the assistant message into chat_messages and the outcome here.
-- So a reply survives a refresh, a closed tab or a phone that put the browser to sleep: the page only polls this row.
--
-- One row per player (their latest request). The player reads it (RLS); only the function writes it, with the
-- service role. Account deletion cascades through profiles.

create table public.chat_runs (
  user_id text primary key default public.requesting_user_id() references public.profiles(id) on delete cascade,
  status text not null check (status in ('running', 'done', 'error')),
  error text,
  started_at timestamptz not null default now(),
  finished_at timestamptz
);

alter table public.chat_runs enable row level security;
create policy chat_runs_select on public.chat_runs for select to authenticated
  using (user_id = (select public.requesting_user_id()));
revoke all on public.chat_runs from anon, authenticated;
grant select on public.chat_runs to authenticated;
